import {initCreationInteractions} from './creation-interactions.js';
import {patchMarkup} from './stable-dom.js';
export const MAX_WORKSPACES=20;
export function normalizeCollections(state){
 const seen=new Set();state.workspaces=(Array.isArray(state.workspaces)?state.workspaces:[{id:'night',name:'夜晚电台'},{id:'sunset',name:'日落系列'}]).filter(w=>w&&typeof w.id==='string'&&!['all','trash','default','speech','abc'].includes(w.id)&&!seen.has(w.id)&&seen.add(w.id)).slice(0,MAX_WORKSPACES).map(w=>({id:w.id,name:String(w.name||'未命名工作区').trim().slice(0,30)}));
 state.workspaces.unshift({id:'speech',name:'Speech',fixed:true},{id:'abc',name:'ABC',fixed:true});
 const valid=new Set(['default',...state.workspaces.map(w=>w.id)]);state.drafts.forEach(d=>{if(!valid.has(d.workspace)||['speech','abc'].includes(d.type)&&d.workspace==='default')d.workspace=['speech','abc'].includes(d.type)?d.type:'default';if(d.form)d.form.workspace=d.workspace;d.trashed=!!d.trashed;});
}
export function createWorkspace(state,name,id){const value=String(name||'').trim().slice(0,30);if(!value)throw Error('请填写工作区名称。');if(state.workspaces.filter(w=>!['speech','abc'].includes(w.id)).length>=MAX_WORKSPACES)throw Error('已达到 20 个自定义工作区上限。');if(state.workspaces.some(w=>w.name.toLocaleLowerCase()===value.toLocaleLowerCase()))throw Error('已有同名工作区，请换一个名字。');const w={id,name:value};state.workspaces.push(w);return w;}
export function deleteWorkspace(state,id){const workspace=state.workspaces.find(w=>w.id===id);if(!workspace||['all','trash','default','speech','abc'].includes(id))return null;const movedIds=[];state.drafts.forEach(d=>{if(d.workspace!==id)return;d.workspace='default';if(d.form)d.form.workspace='default';movedIds.push(d.id);});if(state.form?.workspace===id)state.form.workspace='default';state.workspaces=state.workspaces.filter(w=>w.id!==id);return {...workspace,movedIds};}
export function moveCreation(state,id,target){const d=state.drafts.find(d=>d.id===id);if(!d)return false;if(target==='trash'){d.trashed=true;d.removedAt=Date.now();}else{if(target!=='default'&&!state.workspaces.some(w=>w.id===target))return false;d.workspace=target;d.trashed=false;delete d.removedAt;if(d.form)d.form.workspace=target;}return true;}
export function restoreCreation(state,id){const d=state.drafts.find(d=>d.id===id);if(!d)return false;d.trashed=false;delete d.removedAt;return true;}
export function emptyTrash(state){const removed=new Set(state.drafts.filter(d=>d.trashed).map(d=>d.id));state.drafts=state.drafts.filter(d=>!d.trashed);state.albums.forEach(a=>a.tracks=a.tracks.filter(id=>!removed.has(id)));state.liked=state.liked.filter(id=>!removed.has(id));return removed;}
export function initCollections({state,persist,toast,render,editingRemoved,onMove,onPurge,onPlay,materialById,removeMaterial}){
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
 normalizeCollections(state);let scope='all',activeWorkspace=null,movingId=null,renamingId=null,deletingWorkspace=null,draggedId=null,creatingForMove=false;
 const defaultName=type=>({songs:'Songs',sounds:'Sounds',speech:'Speech',abc:'ABC'}[type]||'默认工作区');
 const name=(id,type='songs')=>id==='default'?defaultName(type):state.workspaces.find(w=>w.id===id)?.name||defaultName(type);
 const options=(type=document.body.dataset.creationType||state.form?.type||'songs')=>(['speech','abc'].includes(type)?'':`<option value="default">${defaultName(type)}</option>`)+state.workspaces.map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('');
 function destinations(){const value=$('#draft-workspace').value||state.form.workspace||'default';$('#draft-workspace').innerHTML=options();$('#draft-workspace').value=state.workspaces.some(w=>w.id===value)?value:['speech','abc'].includes(document.body.dataset.creationType)?document.body.dataset.creationType:'default';$('#move-workspace').innerHTML=options();}
 function renderToolbar(){
  const trash=state.drafts.filter(d=>d.trashed).length;$('#new-workspace').disabled=state.workspaces.filter(w=>!['speech','abc'].includes(w.id)).length>=MAX_WORKSPACES;$('#new-workspace').title='新建工作区 · '+state.workspaces.filter(w=>!['speech','abc'].includes(w.id)).length+' / '+MAX_WORKSPACES;
  const current=scope==='workspace'&&state.workspaces.find(w=>w.id===activeWorkspace),deleteButton=$('#delete-workspace');deleteButton.disabled=!current||['speech','abc'].includes(current.id);deleteButton.title=current&&['speech','abc'].includes(current.id)?current.name+' 是固定工作区，不能删除':current?'删除工作区「'+current.name+'」':'选择工作区后可删除';deleteButton.setAttribute('aria-label',deleteButton.title);
  $$('[data-draft-scope]').forEach(b=>{const active=b.dataset.draftScope===scope;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
  const shelf=$('#workspace-shelf'),scrollLeft=shelf.scrollLeft;
  patchMarkup(shelf,state.workspaces.filter(w=>!['speech','abc'].includes(w.id)).map(w=>`<div class="workspace-chip ${activeWorkspace===w.id&&scope==='workspace'?'selected':''}"><button type="button" data-select-workspace="${esc(w.id)}" data-drop-target="${esc(w.id)}" aria-pressed="${activeWorkspace===w.id&&scope==='workspace'}" title="${esc(w.name)} · 拖入作品移至此工作区">${icon('folder')}<span>${esc(w.name)}</span><small>${state.drafts.filter(d=>!d.trashed&&d.workspace===w.id).length}</small></button>${w.id==='speech'?'':`<button type="button" data-rename-workspace="${esc(w.id)}" aria-label="重命名 ${esc(w.name)}">${icon('create')}</button>`}</div>`).join('')||'<p class="workspace-inline-empty">暂无工作区</p>');
  shelf.scrollLeft=scrollLeft;
  $('#collection-caption').textContent=['songs','speech','sounds','abc'].includes(scope)?({songs:'Songs · 音乐作品',speech:'Speech · 语音作品',sounds:'Sounds · 音效作品',abc:'ABC · 乐谱与音乐作品'}[scope]+'，包含各工作区中的创作。'):scope==='trash'?'移除的作品可恢复到原工作区。':scope==='workspace'?activeWorkspace==='speech'?'Speech · 固定语音工作区':name(activeWorkspace)+' · '+state.workspaces.filter(w=>!['speech','abc'].includes(w.id)).length+' / 20 个自定义工作区':'拖动作品到工作区标签或回收站，也可通过作品的「…」移动。';
  $('#draft-empty-description').textContent=['songs','speech','sounds','abc'].includes(scope)?'还没有这类作品，可以在左侧开始创作。':scope==='trash'?'回收站是空的。':scope==='workspace'?'通过拖动或作品的「…」菜单，将创作移入工作区。':'在左侧开始创作，生成的作品会显示在这里。';
 }
 function showWorkspaceDialog(id=null){if(!id&&state.workspaces.filter(w=>!['speech','abc'].includes(w.id)).length>=MAX_WORKSPACES){toast('最多创建 20 个自定义工作区。');return;}renamingId=id;$('#workspace-dialog-title').textContent=id?'重命名工作区':'新建工作区';$('#workspace-name').value=id?name(id):'';$('#workspace-name').setCustomValidity('');$('#workspace-limit').textContent=`${state.workspaces.filter(w=>!['speech','abc'].includes(w.id)).length} / 20 个自定义工作区`;
  $('#workspace-dialog').showModal();$('#workspace-name').focus();
 }
 function move(id,target){if(!moveCreation(state,id,target))return;if(target==='trash')editingRemoved?.(id);else onMove?.(id,target);persist();render();toast(target==='trash'?'作品已移入回收站，可随时恢复。':'已移入「'+name(target,state.drafts.find(d=>d.id===id)?.type)+'」。');}
 function actions(d){return d.trashed?`<button data-restore-creation="${esc(d.id)}">恢复到原工作区</button><button data-move-creation="${esc(d.id)}">恢复至其他工作区</button>`:`<button data-move-creation="${esc(d.id)}">移入工作区</button><button class="trash-action" data-trash-creation="${esc(d.id)}">移入回收站</button>`;}
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
  if(b.id==='delete-workspace'&&!['speech','abc'].includes(activeWorkspace)&&scope==='workspace'&&state.workspaces.some(w=>w.id===activeWorkspace)){deletingWorkspace=activeWorkspace;const count=state.drafts.filter(d=>d.workspace===deletingWorkspace).length;$('#delete-workspace-description').textContent='将删除「'+name(deletingWorkspace)+'」，其中 '+count+' 个作品会移回默认工作区。';$('#delete-workspace-dialog').showModal();$('#cancel-delete-workspace').focus();}
  if(b.id==='confirm-delete-workspace'){const removed=deleteWorkspace(state,deletingWorkspace);if(removed){removed.movedIds.forEach(id=>onMove?.(id,'default'));scope='all';activeWorkspace=null;destinations();persist();render();toast('「'+removed.name+'」已删除，作品已保留。');}$('#delete-workspace-dialog').close();$('[data-draft-scope="all"]').focus({preventScroll:true});}
  if(b.dataset.draftScope){scope=b.dataset.draftScope;activeWorkspace=null;render();}
  if(b.dataset.selectWorkspace){scope='workspace';activeWorkspace=b.dataset.selectWorkspace;render();$$('[data-select-workspace]').find(button=>button.dataset.selectWorkspace===activeWorkspace)?.focus({preventScroll:true});}
  if(b.id==='new-workspace')showWorkspaceDialog();if(b.dataset.renameWorkspace&&!['speech','abc'].includes(b.dataset.renameWorkspace))showWorkspaceDialog(b.dataset.renameWorkspace);
  if(b.dataset.closeCreator){if(b.dataset.closeCreator==='workspace-dialog'&&creatingForMove){creatingForMove=false;movingId=null;}$('#'+b.dataset.closeCreator).close();}
  if(b.dataset.moveCreation){movingId=b.dataset.moveCreation;$('#move-work-title').textContent='「'+(state.drafts.find(d=>d.id===movingId)?.title||'作品')+'」';$('#move-workspace').innerHTML=options(state.drafts.find(d=>d.id===movingId)?.type);$('#move-workspace').value=state.drafts.find(d=>d.id===movingId)?.workspace||'default';$('#move-work-dialog').showModal();b.closest('details')?.removeAttribute('open');}
  if(b.id==='create-while-moving'){creatingForMove=true;$('#move-work-dialog').close();showWorkspaceDialog();}
  if(b.dataset.trashCreation)move(b.dataset.trashCreation,'trash');
  if(b.dataset.restoreCreation){restoreCreation(state,b.dataset.restoreCreation);persist();render();toast('作品已恢复到原工作区。');}
  if(b.id==='clear-trash'){$('#empty-trash-description').textContent='将移除回收站中的 '+state.drafts.filter(d=>d.trashed).length+' 个作品。';$('#empty-trash-dialog').showModal();}
  if(b.id==='confirm-empty-trash'){const ids=emptyTrash(state);onPurge?.(ids);persist();$('#empty-trash-dialog').close();render();toast('回收站已清空。');}
 });
 $('#workspace-name').addEventListener('input',e=>e.target.setCustomValidity(''));
 $('#workspace-form').addEventListener('submit',e=>{e.preventDefault();const value=$('#workspace-name').value.trim();try{if(renamingId){if(!value)throw Error('请填写工作区名称。');if(state.workspaces.some(w=>w.id!==renamingId&&w.name.toLocaleLowerCase()===value.toLocaleLowerCase()))throw Error('已有同名工作区。');state.workspaces.find(w=>w.id===renamingId).name=value;}else{const w=createWorkspace(state,value,'workspace-'+crypto.randomUUID());activeWorkspace=w.id;scope='workspace';}persist();destinations();$('#workspace-dialog').close();render();if(movingId){$('#move-workspace').value=activeWorkspace||'default';creatingForMove=false;$('#move-work-dialog').showModal();}else if(activeWorkspace)$$('[data-select-workspace]').find(button=>button.dataset.selectWorkspace===activeWorkspace)?.scrollIntoView({block:'nearest',inline:'nearest'});toast(renamingId?'工作区名称已更新。':'工作区已创建。');}catch(error){$('#workspace-name').setCustomValidity(error.message);$('#workspace-name').reportValidity();}});
 $('#move-work-form').addEventListener('submit',e=>{e.preventDefault();move(movingId,$('#move-workspace').value);movingId=null;$('#move-work-dialog').close();});
 $('#move-work-dialog').addEventListener('close',()=>{if(!creatingForMove)movingId=null;});
 $('#workspace-dialog').addEventListener('cancel',()=>{creatingForMove=false;movingId=null;});
 $('#delete-workspace-dialog').addEventListener('close',()=>{deletingWorkspace=null;});
 initCreationInteractions({resolve:id=>state.drafts.find(d=>d.id===id)||materialById?.(id),onMove:(id,target)=>state.drafts.some(d=>d.id===id)?move(id,target):target==='trash'?removeMaterial?.(id):toast('上传素材请在素材管理中整理。'),onPlay});
 destinations();return {move,name,actions,renderToolbar,refreshDestinations:destinations,isTrash:()=>scope==='trash',visible:()=>state.drafts.filter(d=>scope==='trash'?d.trashed:!d.trashed&&(scope!=='workspace'||d.workspace===activeWorkspace)&&(!['songs','speech','sounds','abc'].includes(scope)||(d.type||'songs')===scope)),showAll:()=>{const changed=scope!=='all';scope='all';activeWorkspace=null;renderToolbar();return changed;}};
}
